INSERT INTO FactCashBalances (SK_CustomerID, SK_AccountID, SK_DateID, BatchID, Cash) SELECT DA.SK_CustomerID AS SK_CustomerID, DA.SK_AccountID AS SK_AccountID, DD.SK_DateID AS SK_DateID, 1 AS BatchID, SUM(CT_AMT) AS Cash FROM Source.CashTransaction AS CT, DimAccount AS DA, DimDate AS DD WHERE CT.CT_CA_ID = DA.AccountID AND CAST(CT_DTS AS DATE) BETWEEN DA.EffectiveDate AND DA.EndDate AND CAST(CT_DTS AS DATE) = DD.DateValue GROUP BY DA.SK_CustomerID, DA.SK_AccountID, DD.SK_DateID, CAST(CT_DTS AS DATE);
